insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p126', 'allemand', '3AS', 15, 126, 'L6 3AS p126 — Informationen : Wie Jugendliche ihr Handy nutzen (84 % · 34 Franken · Klingeltöne · Prepaid)', E'Informationen\nWie nützen die Jugendlichen ihr Handy ?\nWie Jugendliche ihr Handy nutzen\nDie Verbreitung von Handys unter jungen Europäern nimmt ständig zu. Nach einer neuen Studie haben inzwischen 84 % der Europäer zwischen 12 und 14 Jahren ein Mobiltelefon. Pro Monat zahlen die Jugendlichen dieser Altersgruppe in der Schweiz etwa 40 Franken, der europäische Durchschnitt liegt bei 34 Franken pro Monat.\nJugendliche sind offener als Erwachsene, was neue Dienste und Funktionen angeht - hauptsächlich interessieren sie sich neben telefonieren und SMS für Klingeltöne und News-Ticker. Über 60 % der jungen Kunden nutzen diese beiden Angebote. 65% wünschen sich ein Handy, das einen Musikplayer hat. Nur 34% wünschen sich, dass ihr Handy einen Zugang zum Internet bietet.\nGerade in dieser Zielgruppe zeigt sich, dass das Preis - Leistungs - Verhältnis stimmen muss. Denn obwohl die Nutzer in dieser Altersgruppe durchaus technikfreundlich und neugierig sind, nutzen sie nur solche Angebote, die dieses Kriterium erfüllen. Dreiviertel der Nutzer unter 15 Jahren haben ein Prepaid - Handy, dagegen haben rund 62 % der Handykunden zwischen 21 und 24 Jahren einen Vertrag mit einer bestimmten Laufzeit.\nFotos : drei Handys (klappbar · Nokia · Motorola).', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p127', 'allemand', '3AS', 15, 127, 'L6 3AS p127 — Wortschatz L6 (Substantive/Adjektive/Adverbien/Funktionswörter/Verben)', E'Wortschatz\nSubstantive : der Absender · der Anspruch · der Aufkleber · der Auftrag · das Bedürfnis · die Beförderung · der Bereich · der Daumen · der Empfänger · die Entfernung · die Fernmeldung · die Gebühr · das Internet · das Jodeln · der Kontakt · das Mobiltelefon · das Postamt · die Postleitzahl · das Postwesen · die SMS · die Taste · die Utopie · der Zettel\nAdjektive : flink · findig · geschäftlich · überraschend · weltweit\nAdverbien/Ausdrücke : durchaus · inzwischen · jeweils · normalerweise · stets · ziemlich\nFunktionswörter : innerhalb + Genitiv · trotz + Genitiv / Dativ\nVerben : an/treten · sich ändern · auf/geben · auf/kleben · aus/füllen · aus/kommen · aus/schalten · befördern · begegnen + Dativ · begründen · chatten · drücken · ein/schalten · ein/schränken · enthalten · kommunizieren · nach/denken · nach/gucken · surfen · tippen · übersehen · überwinden · verbinden mit · verschicken · verständigen · wachsen', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p129', 'allemand', '3AS', 16, 129, 'L7 3AS p129 — Jugendprobleme (ouverture Lektion 7)', E'Lektion 7 — Jugendprobleme (ouverture)\nFotos : Motocross-Fahrer · Motorradrennen (Nr. 2) · Fußball-Rauferei · Gruppe Jugendlicher.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p130', 'allemand', '3AS', 16, 130, 'L7 3AS p130 — Jugend und Drogen (Text + R/F)', E'1. Was fällt Ihnen ein zu Jugend ?\n2. Lesen Sie den Text.\nJugend und Drogen\nDie Jugend ist die Lebensphase zwischen Kindheit und Erwachsenenalter. Für viele Jugendlichen ist sie eine Periode von Schulproblemen : Lernstoff nicht schaffen, schlechte Leistungen …\nSie ist auch die Zeit der Unsicherheit über ihre Rolle und Identität. Man ist unsicher und braucht etwas, um sich sicherer zu fühlen. Wenn die Jugendlichen Drogen nähmen, würden sie sich sicherer fühlen.\nDer Drogenkonsum bei Jugendlichen ist seit Jahren im Focus der Medien. So erscheinen immer wieder Berichte über Einzelschicksale von opiatabhängigen Jugendlichen.\nDie Zahl der Erstkonsumenten von Drogen steigt in Deutschland dramatisch an.\nNach Angaben des Bundesinnenministeriums stieg auch die Zahl der Rauschgiftfunde deutlich an.\nAber was sind eigentlich Drogen ?\nAls Drogen sind bezeichnet, alle Stoffe, die eine negative Wirkung auf den Menschen haben und die zur Süchtigkeit bringen Wie zum Beispiel : Alkohol, Tabak, Schlafmittel, Kokain.\nSogar Kaffee gehört dazu, denn man kann kaffeesüchtig sein.\nUm das Drogenproblem zu lösen, soll man schon in die Schulen gehen und dort Projektwochen veranstalten, um das Bewusstsein der Kinder und der Jugendlichen zu stärken, denn Neugier kann die Jugend an den Tod bringen…\n3. Stimmt ? Stimmt das nicht ? Kreuzen Sie an. (R/F)\n- Die Jugend hat keine Probleme.\n- Die Jugend ist Zeit der Sicherheit.\n- Die Jugendlichen wollen alles probieren.\n- Drogen sind nicht gefährlich.', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
insert into public.lesson_content (id, subject, level, unite, page, titre, body, free) values ('3as-p131', 'allemand', '3AS', 16, 131, 'L7 3AS p131 — Ergänzen + Synonyme + Gegenteile + Was passt zusammen + Antworten', E'4. Ergänzen Sie. (Jugend · probieren · ansteigen · Lebensphase · Drogen)\n- Die Zahl der Drogenkonsumenten ……… ständig ………\n- Zu den ……… gehört auch der Kaffee.\n- Die ……… trifft viele Schwierigkeiten in der Gesellschaft.\n- Aus Neugier wollen die Jugendlichen alles ………\n- Das 3. Alter ist eine ………\n5. Ersetzen Sie die hier unterstrichenen Wörter durch Synonyme oder gleichbedeutende Wörter aus dem Text.\n- Wegen Stress hat sich die Zahl der Schlafmittelverbraucher erhöht.\n- Für viele Leute ist die Kindheit die schönste Lebenszeit.\n- Heutzutage verbrauchen die Menschen viele Süßigkeiten.\n- Der Mensch kann vom Kaffee abhängig sein.\n6. Ergänzen Sie mit dem passenden Gegenteil.\n- Die Zahl der Tabakraucher hat sich in den letzten Jahren nicht erhöht, sondern ………\n- Die Erwachsenen sind gleichgültig, dagegen sind die Jugendlichen ………\n- Viele Jugendlichen sind sicher, dagegen sind andere ………\n- Einige Jugendlichen verhalten sich positiv, dagegen hat eine Minderheit ein ……… Verhalten.\n7. Was passt zusammen ?\n1. Drogen sind — c) Stoffe, die die Reaktionen des Körpers verändern.\n2. Unter Drogenmissbrauch — d) versteht man den häufigen und unkontrollierbaren Gebrauch von Drogen\n3. Drogenabhängigkeit liegt vor — a) wenn man immer größere oder stärkere Mengen einer Droge braucht.\n4. Die Ursache der Abhängigkeit — b) ist häufig ein berufliches oder familiäres Problem.\n8. Antworten Sie.\n1. Welche Schulprobleme haben die Jugendlichen ?\n2. Warum nehmen die Jugendlichen Drogen ?\n3. Welche Wirkungen haben die Drogen auf den Menschen ?\n4. Was könnte man machen, um dieses Problem abzuschaffen ?', false) on conflict (id) do update set body = excluded.body, titre = excluded.titre;
